// Express-style middleware sketch
function rbac(requiredRoles){
  return (req,res,next)=>{
    const token=req.headers.authorization?.split(' ')[1];
    const payload=verifyJwt(token); // assume helper
    if(!payload || !requiredRoles.includes(payload.role)) return res.status(403).send('Forbidden');
    req.user=payload; next();
  };
}
