  const event = {
    userId,
    event,
    user_tier: userTier  // Optional; defaults to null for old consumers
  };
  await kafkaProducer.send({
    topic: 'user-events',
    messages: [{ value: avroSerializer.serialize(event) }]
  });
};

// Consumer: Handle both old and new schemas gracefully
const consumeUserEvent = async (message) => {
  const event = avroDeserializer.deserialize(message.value);
  // Safely access optional field with fallback
  const tier = event.user_tier ?? 'free';
  console.log(`User ${event.userId} at tier: ${tier}`);
};
